"""The three-day letter and a small optional daily choice: no model decides their effects."""
from story_data import S,N,R,ch

S('life15_letter_start',{
 'start':N('kol','К вам приходит письмо с воли. В личном деле значится: {case}. Шкет замечает конверт и тут же отводит взгляд: «Не спрашиваю, что там. Просто... у меня тоже дома ждут». В письме нет обещания, что всё исправится. Есть лишь несколько строк от человека, которому вы ещё не безразличны.',
  ch('Показать Шкету только подпись, не содержание',R('Он не читает дальше подписи. «Хорошо, что кто-то пишет», — говорит он, освобождая место за столом.',{'life_letter':'share','karma':{'empathy':1}})),
  ch('Убрать конверт: это только ваше',R('Вы складываете лист и прячете. Никто не обязан объяснять свой дом соседу.',{'life_letter':'quiet'})),
  ch('Помочь Шкету начать своё письмо',R('Вы нашли для него бумагу и первые слова. Ваш собственный конверт подождёт.',{'life_letter':'help','karma':{'empathy':2},'rel':{'kol':3}})))
},story=True,trig={'loc':0,'day':2,'after':['c1_intro']},title='Письмо из дома · день первый',memo='Игрок прочёл письмо из дома и решил, кому доверить этот разговор.',know=['kol'])

S('life15_letter_middle',{
 'start':N('kol','{letter_intro} Утром чужие хлопоты продолжаются: раздача, работа, проверка. На столе лежит чистый лист. Ответить — значит выбрать слова; промолчать тоже выбор.',
  ch('Написать честно о трудном дне',R('Вы пишете без красивых обещаний. Письмо уходит через почту; когда оно дойдёт, никто здесь сказать не может.',{'life_letter':'honest','karma':{'honor':2}})),
  ch('Написать коротко, чтобы не тревожить близких',R('Вы сообщаете главное и сохраняете остальное для другой встречи. Ответ уходит через почту.',{'life_letter':'polite'})),
  ch('Не отправлять письмо сегодня',R('Чистый лист остаётся на столе. Вы не готовы говорить за весь свой срок одним письмом.',{'life_letter':'postpone'})))
},story=True,trig={'loc':0,'after':['life15_letter_start'],'life_days':1},title='Письмо из дома · день второй',memo='Игрок выбрал, отвечать ли домой и как.',know=['kol'])

S('life15_letter_end',{
 'start':N('kol','{letter_end_intro} Шкет молча кладёт рядом свой лист. «Не знаю, что дома ответят, — говорит он. — Может, ничего. Но мне легче, когда я хотя бы пытаюсь».',
  ch('Не обещать невозможного, но сохранить связь',R('Вы оставляете место для ещё одного письма. Это не побег и не оправдание, лишь возможность продолжить разговор.',{'life_letter':'keep_link','karma':{'honor':2}})),
  ch('Помочь соседу довести его письмо до конца',R('Вы помогаете Шкету найти слова. Ни его семья, ни ваша не обязаны ответить сразу, но теперь у него есть адресованный лист.',{'life_letter':'support_neighbor','karma':{'empathy':2},'rel':{'kol':6}})),
  ch('Пока убрать письмо подальше',R('Конверт остаётся с вами. Разговор не закончен навсегда: сегодня нужны силы просто прожить день.',{'life_letter':'close','stamina':5})))
},story=True,trig={'loc':0,'after':['life15_letter_middle'],'life_days':2,'life_after_middle':True},title='Письмо из дома · день третий',memo='Игрок решил, что делать со связью с домом после трёх дней размышлений.',know=['kol'])

S('life15_round',{
 'start':N(None,'Утренний распорядок: очередь у раздачи, путь на работу, свёрнутые одеяла. Сегодня у вас есть немного времени до следующего дела. Никто не знает, каким будет вечер.',
  ch('Поделиться частью пайки (−6 сытости)',R('Вы отдали часть своего завтрака. Этого мало, чтобы всё исправить, но человек рядом запомнил.',{'life_routine':'share'}),req={'food':6}),
  ch('Сохранить пайку и перевести дух (+5 сил)',R('Вы оставили свою порцию себе. Заботиться о себе здесь тоже необходимо.',{'life_routine':'keep'})),
  ch('Выслушать кого-то в очереди',R('Вы выслушали чужой день, не пообещав невозможного. Разговор остался между вами.',{'life_routine':'listen'})))
},rep=True,title='Утренний распорядок')
